changeSet.sql:
DELETE FROM USER_SDO_GEOM_METADATA WHERE TABLE_NAME='BRANCHES' AND COLUMN_NAME='LOCATION';
INSERT INTO USER_SDO_GEOM_METADATA VALUES (
    'BRANCHES', 'LOCATION',
    MDSYS.SDO_DIM_ARRAY(
        MDSYS.SDO_DIM_ELEMENT('LONGITUDE',-180,180,0.005),
        MDSYS.SDO_DIM_ELEMENT('LATITUDE',-90,90,0.005)
    ), 8307
);

BEGIN
    EXECUTE IMMEDIATE '
        CREATE INDEX MERIDIAN.IDX_BRANCH_LOCATION
        ON MERIDIAN.BRANCHES (LOCATION)
        INDEXTYPE IS MDSYS.SPATIAL_INDEX
    ';
EXCEPTION
    WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
